CREATE TABLE public.achievements (id text NOT NULL, name text NOT NULL, description text NOT NULL, icon text NOT NULL, type text NOT NULL, tiers jsonb, rarity text NOT NULL, category text NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.admin_audit_log (id uuid DEFAULT gen_random_uuid() NOT NULL, admin_id uuid NOT NULL, action text NOT NULL, target_id uuid, target_type text, payload jsonb DEFAULT '{}'::jsonb, created_at timestamp with time zone DEFAULT now(), PRIMARY KEY (id));
CREATE TABLE public.answer_types (id integer DEFAULT nextval('answer_types_id_seq'::regclass) NOT NULL, name text NOT NULL, UNIQUE (name), PRIMARY KEY (id));
CREATE TABLE public.custom_playlist_tracks (id uuid DEFAULT gen_random_uuid() NOT NULL, playlist_id uuid NOT NULL, artist text, title text, preview_url text, cover_url text, source text DEFAULT 'manual'::text NOT NULL, external_id text, "position" integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, custom_artist text, custom_title text, custom_feats text[], preview_expires_at timestamp with time zone, track_id uuid NOT NULL, PRIMARY KEY (id), UNIQUE (playlist_id, track_id));
CREATE TABLE public.custom_playlists (id uuid DEFAULT gen_random_uuid() NOT NULL, owner_id uuid DEFAULT auth.uid() NOT NULL, name text NOT NULL, emoji text DEFAULT '🎵'::text NOT NULL, is_public boolean DEFAULT false NOT NULL, track_count integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, is_official boolean DEFAULT false NOT NULL, linked_room_id text, PRIMARY KEY (id));
CREATE TABLE public.daily_results (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, date date NOT NULL, attempts integer NOT NULL, won boolean NOT NULL, solve_time_seconds integer, guesses jsonb DEFAULT '[]'::jsonb NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id), UNIQUE (user_id, date));
CREATE TABLE public.daily_songs (id uuid DEFAULT gen_random_uuid() NOT NULL, date date NOT NULL, track_id uuid NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, UNIQUE (date), PRIMARY KEY (id));
CREATE TABLE public.follows (id bigserial NOT NULL, follower_id uuid NOT NULL, following_id uuid NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, UNIQUE (follower_id, following_id), PRIMARY KEY (id));
CREATE TABLE public.friendships (id bigserial NOT NULL, requester_id uuid NOT NULL, addressee_id uuid NOT NULL, status text DEFAULT 'pending'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, accepted_at timestamp with time zone, PRIMARY KEY (id), UNIQUE (requester_id, addressee_id));
CREATE TABLE public.game_players (id uuid DEFAULT gen_random_uuid() NOT NULL, game_id uuid NOT NULL, user_id uuid, username text NOT NULL, score integer DEFAULT 0 NOT NULL, rank integer, is_guest boolean DEFAULT false NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.game_results (id uuid DEFAULT gen_random_uuid() NOT NULL, game_id uuid NOT NULL, user_id uuid, username text NOT NULL, score integer NOT NULL, rank integer NOT NULL, total_players integer NOT NULL, room_name text NOT NULL, room_emoji text, achievement_ids text[] DEFAULT '{}'::text[] NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.games (id uuid DEFAULT gen_random_uuid() NOT NULL, room_id text NOT NULL, started_at timestamp with time zone DEFAULT now() NOT NULL, ended_at timestamp with time zone, rounds integer DEFAULT 10 NOT NULL, mode text DEFAULT 'classic'::text NOT NULL, source text DEFAULT 'web'::text NOT NULL, player_count integer, origin text, PRIMARY KEY (id));
CREATE TABLE public.notifications (id bigserial NOT NULL, user_id uuid NOT NULL, type text NOT NULL, actor_id uuid NOT NULL, payload jsonb DEFAULT '{}'::jsonb NOT NULL, read boolean DEFAULT false NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.pro_subscriptions (user_id uuid NOT NULL, plan text NOT NULL, status text DEFAULT 'active'::text NOT NULL, current_period_end timestamp with time zone NOT NULL, stripe_customer_id text, stripe_subscription_id text, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, stripe_last_session text, PRIMARY KEY (user_id));
CREATE TABLE public.profiles (id uuid NOT NULL, username text NOT NULL, avatar_url text, xp integer DEFAULT 0 NOT NULL, level integer DEFAULT 1 NOT NULL, elo integer DEFAULT 1000 NOT NULL, games_played integer DEFAULT 0 NOT NULL, total_score integer DEFAULT 0 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, role text DEFAULT 'user'::text NOT NULL, is_private boolean DEFAULT false NOT NULL, current_streak integer DEFAULT 0 NOT NULL, best_streak integer DEFAULT 0 NOT NULL, last_played_date date, win_streak integer DEFAULT 0 NOT NULL, best_win_streak integer DEFAULT 0 NOT NULL, featured_achievements text[] DEFAULT '{}'::text[] NOT NULL, discord_id text, discord_username text, discord_avatar text, discord_games_played integer DEFAULT 0 NOT NULL, UNIQUE (discord_id), PRIMARY KEY (id), UNIQUE (username));
CREATE TABLE public.reports (id uuid DEFAULT gen_random_uuid() NOT NULL, type text NOT NULL, status text DEFAULT 'pending'::text NOT NULL, reporter_id uuid, reporter_name text, reporter_email text, reported_user_id uuid, reported_username text, room_id text, subject text, message text NOT NULL, metadata jsonb DEFAULT '{}'::jsonb, created_at timestamp with time zone DEFAULT now(), resolved_at timestamp with time zone, resolved_by uuid, admin_note text, admin_reply text, PRIMARY KEY (id));
CREATE TABLE public.room_playlists (room_id uuid NOT NULL, playlist_id uuid NOT NULL, "position" integer DEFAULT 0 NOT NULL, PRIMARY KEY (room_id, playlist_id));
CREATE TABLE public.rooms (id uuid DEFAULT gen_random_uuid() NOT NULL, code text NOT NULL, name text NOT NULL, emoji text DEFAULT '🎵'::text NOT NULL, description text DEFAULT ''::text, owner_id uuid NOT NULL, playlist_id uuid, is_public boolean DEFAULT true NOT NULL, max_rounds integer DEFAULT 10 NOT NULL, round_duration integer DEFAULT 30 NOT NULL, break_duration integer DEFAULT 7 NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, last_active_at timestamp with time zone DEFAULT now() NOT NULL, is_official boolean DEFAULT false NOT NULL, auto_start boolean DEFAULT false NOT NULL, game_mode text DEFAULT 'classic'::text NOT NULL, UNIQUE (code), PRIMARY KEY (id));
CREATE TABLE public.site_settings (key text NOT NULL, value jsonb DEFAULT '{}'::jsonb NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (key));
CREATE TABLE public.track_answers (id uuid DEFAULT gen_random_uuid() NOT NULL, track_id uuid NOT NULL, answer_type_id integer NOT NULL, value text NOT NULL, PRIMARY KEY (id));
CREATE TABLE public.track_stats (track_id uuid NOT NULL, rounds_played integer DEFAULT 0 NOT NULL, players_exposed integer DEFAULT 0 NOT NULL, found_full integer DEFAULT 0 NOT NULL, last_played_at timestamp with time zone, PRIMARY KEY (track_id));
CREATE TABLE public.tracks (id uuid DEFAULT gen_random_uuid() NOT NULL, artist text NOT NULL, title text NOT NULL, norm_key text GENERATED ALWAYS AS ((lower(btrim(artist)) || '|'::text) || lower(btrim(title))) STORED, preview_url text, preview_expires_at timestamp with time zone, cover_url text, external_id text, source text DEFAULT 'manual'::text NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, youtube_id text, card_id uuid, card_checked_at timestamp with time zone, UNIQUE (norm_key), PRIMARY KEY (id));
CREATE TABLE public.user_achievements (id uuid DEFAULT gen_random_uuid() NOT NULL, user_id uuid NOT NULL, achievement_id text NOT NULL, tier text, unlocked_at timestamp with time zone DEFAULT now() NOT NULL, count integer DEFAULT 1 NOT NULL, PRIMARY KEY (id), UNIQUE NULLS NOT DISTINCT (user_id, achievement_id, tier));
CREATE TABLE public.visit_sources (id uuid DEFAULT gen_random_uuid() NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, source text NOT NULL, medium text NOT NULL, campaign text, referrer_host text, landing_path text, PRIMARY KEY (id));
CREATE TABLE public.weekly_challenge_contributions (id uuid DEFAULT gen_random_uuid() NOT NULL, challenge_id uuid NOT NULL, user_id uuid NOT NULL, amount integer DEFAULT 0 NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, UNIQUE (challenge_id, user_id), PRIMARY KEY (id));
CREATE TABLE public.weekly_challenges (id uuid DEFAULT gen_random_uuid() NOT NULL, week_start date NOT NULL, week_end date NOT NULL, type text NOT NULL, target integer NOT NULL, current_value integer DEFAULT 0 NOT NULL, status text DEFAULT 'active'::text NOT NULL, top_contributor_id uuid, top_contributor_amount integer, created_at timestamp with time zone DEFAULT now() NOT NULL, closed_at timestamp with time zone, PRIMARY KEY (id), UNIQUE (week_start));
CREATE TABLE public.zikle_pool (track_id uuid NOT NULL, added_at timestamp with time zone DEFAULT now() NOT NULL, PRIMARY KEY (track_id));
ALTER TABLE public.game_players ADD CONSTRAINT game_players_game_id_fkey FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE;
ALTER TABLE public.game_players ADD CONSTRAINT game_players_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_id_fkey FOREIGN KEY (id) REFERENCES auth.users(id) ON DELETE CASCADE;
ALTER TABLE public.rooms ADD CONSTRAINT rooms_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.rooms ADD CONSTRAINT rooms_playlist_id_fkey FOREIGN KEY (playlist_id) REFERENCES custom_playlists(id) ON DELETE SET NULL;
ALTER TABLE public.user_achievements ADD CONSTRAINT user_achievements_achievement_id_fkey FOREIGN KEY (achievement_id) REFERENCES achievements(id) ON DELETE CASCADE;
ALTER TABLE public.user_achievements ADD CONSTRAINT user_achievements_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.game_results ADD CONSTRAINT game_results_game_id_fkey FOREIGN KEY (game_id) REFERENCES games(id) ON DELETE CASCADE;
ALTER TABLE public.game_results ADD CONSTRAINT game_results_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.zikle_pool ADD CONSTRAINT zikle_pool_track_id_fkey FOREIGN KEY (track_id) REFERENCES tracks(id) ON DELETE CASCADE;
ALTER TABLE public.daily_songs ADD CONSTRAINT daily_songs_track_id_fkey FOREIGN KEY (track_id) REFERENCES tracks(id);
ALTER TABLE public.track_answers ADD CONSTRAINT track_answers_answer_type_id_fkey FOREIGN KEY (answer_type_id) REFERENCES answer_types(id);
ALTER TABLE public.track_answers ADD CONSTRAINT track_answers_track_id_fkey FOREIGN KEY (track_id) REFERENCES custom_playlist_tracks(id) ON DELETE CASCADE;
ALTER TABLE public.custom_playlist_tracks ADD CONSTRAINT custom_playlist_tracks_playlist_id_fkey FOREIGN KEY (playlist_id) REFERENCES custom_playlists(id) ON DELETE CASCADE;
ALTER TABLE public.custom_playlist_tracks ADD CONSTRAINT custom_playlist_tracks_track_id_fkey FOREIGN KEY (track_id) REFERENCES tracks(id);
ALTER TABLE public.daily_results ADD CONSTRAINT daily_results_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.custom_playlists ADD CONSTRAINT custom_playlists_owner_id_fkey FOREIGN KEY (owner_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.weekly_challenges ADD CONSTRAINT weekly_challenges_top_contributor_id_fkey FOREIGN KEY (top_contributor_id) REFERENCES profiles(id) ON DELETE SET NULL;
ALTER TABLE public.weekly_challenge_contributions ADD CONSTRAINT weekly_challenge_contributions_challenge_id_fkey FOREIGN KEY (challenge_id) REFERENCES weekly_challenges(id) ON DELETE CASCADE;
ALTER TABLE public.weekly_challenge_contributions ADD CONSTRAINT weekly_challenge_contributions_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.follows ADD CONSTRAINT follows_follower_id_fkey FOREIGN KEY (follower_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.follows ADD CONSTRAINT follows_following_id_fkey FOREIGN KEY (following_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.friendships ADD CONSTRAINT friendships_addressee_id_fkey FOREIGN KEY (addressee_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.friendships ADD CONSTRAINT friendships_requester_id_fkey FOREIGN KEY (requester_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.notifications ADD CONSTRAINT notifications_actor_id_fkey FOREIGN KEY (actor_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.notifications ADD CONSTRAINT notifications_user_id_fkey FOREIGN KEY (user_id) REFERENCES profiles(id) ON DELETE CASCADE;
ALTER TABLE public.room_playlists ADD CONSTRAINT room_playlists_playlist_id_fkey FOREIGN KEY (playlist_id) REFERENCES custom_playlists(id) ON DELETE CASCADE;
ALTER TABLE public.room_playlists ADD CONSTRAINT room_playlists_room_id_fkey FOREIGN KEY (room_id) REFERENCES rooms(id) ON DELETE CASCADE;
ALTER TABLE public.track_stats ADD CONSTRAINT track_stats_track_id_fkey FOREIGN KEY (track_id) REFERENCES tracks(id) ON DELETE CASCADE;
